{
  "source_context": [
    {
      "section": "V1",
      "lyrics": [
        "同じように求めてしまうから",
        "黙って居ればいい？",
        "望むように逆さに歩いてく",
        "息絶えたみたいだ"
      ]
    },
    {
      "section": "V2",
      "lyrics": [
        "潜在的な憂いには",
        "如何にも素直になれず",
        "誰とも訳合えないね",
        "自分さえも"
      ]
    },
    {
      "section": "B1",
      "lyrics": [
        "命令　故意を感じて",
        "訂正　無為を観じて",
        "安寧は罪が混ざる",
        "当然か"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "知った顔で笑っててよ",
        "底知らず恐れるの",
        "月並みの愛をくれよ",
        "You know me",
        "知った気で踊ってるの",
        "底が満たされるの",
        "放さないで止めないで",
        "独りじゃないの"
      ]
    }
  ],
  "section": "V1",
  "phrases": [
    {
      "id": "V1-01",
      "ja": "同じように求めてしまうから",
      "budget": {
        "min": 13,
        "max": 13
      },
      "pattern": [
        4,
        5,
        4
      ]
    },
    {
      "id": "V1-02",
      "ja": "黙って居ればいい？",
      "budget": {
        "min": 6,
        "max": 6
      },
      "pattern": [
        3,
        3
      ]
    },
    {
      "id": "V1-03",
      "ja": "望むように逆さに歩いてく",
      "budget": {
        "min": 13,
        "max": 13
      },
      "pattern": [
        5,
        4,
        4
      ]
    },
    {
      "id": "V1-04",
      "ja": "息絶えたみたいだ",
      "budget": {
        "min": 8,
        "max": 8
      },
      "pattern": [
        5,
        3
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "话没出口 就伸手去要 同一种暖"
        },
        {
          "id": "V1-02",
          "zh": "不作声 就好吗"
        },
        {
          "id": "V1-03",
          "zh": "顺你的心愿 我向后退 脸朝向前"
        },
        {
          "id": "V1-04",
          "zh": "呼吸像停住 一样静"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "还是忍不住 一遍遍去追寻"
        },
        {
          "id": "V1-02",
          "zh": "沉默就够了吗"
        },
        {
          "id": "V1-03",
          "zh": "朝着渴望的方向 倒着慢慢走"
        },
        {
          "id": "V1-04",
          "zh": "像断了呼吸一样"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "总是一样地渴求着"
        },
        {
          "id": "V1-02",
          "zh": "沉默着就好吗"
        },
        {
          "id": "V1-03",
          "zh": "如你所愿倒着走下去"
        },
        {
          "id": "V1-04",
          "zh": "像断了气一样"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "像从前一样 忍不住去渴求"
        },
        {
          "id": "V1-02",
          "zh": "沉默着就好吗"
        },
        {
          "id": "V1-03",
          "zh": "顺着心愿 倒着走也不回头"
        },
        {
          "id": "V1-04",
          "zh": "像断了呼吸一样"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "不知不觉 学你的样子 伸手索求"
        },
        {
          "id": "V1-02",
          "zh": "闭上嘴 就好吗"
        },
        {
          "id": "V1-03",
          "zh": "全按你所愿 倒着向前 一步步走"
        },
        {
          "id": "V1-04",
          "zh": "像断了呼吸 一样静"
        }
      ]
    },
    {
      "label": "F",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "同样地追求着"
        },
        {
          "id": "V1-02",
          "zh": "沉默着就好吗？"
        },
        {
          "id": "V1-03",
          "zh": "如你所愿倒着行走"
        },
        {
          "id": "V1-04",
          "zh": "仿佛已断了气息"
        }
      ]
    }
  ]
}

